/* eslint-disable */
/**
 * # Convert Bun Lockfile to a Nix expression
 *
 * Takes a string input of the contents of a bun lockfile and converts it into a ready to use Nix expression which fetches the packages
 */
export function convert_lockfile_to_nix_expression(contents: string, options: Options): string;
/**
 * # Lockfile conversion options
 *
 * Config options for generating a bun.nix file
 */
export class Options {
  free(): void;
  [Symbol.dispose](): void;
  /**
   * # New Options
   *
   * Constructor for `bun2nix` options
   */
  constructor(copy_prefix: string);
  /**
   * The prefix to use when copying workspace or file packages
   */
  copy_prefix: string;
}
